import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1229, own='cte_152.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)
H("923.d.1.A",3,"An intern at a print shop notices jobs keep piling up at the folding machine, so she breaks down each step and proposes a new order for the workflow. She is:","analyzing elements of a problem to develop creative and innovative solutions",["waiting for the pile to disappear","blaming the machine","avoiding the folding station"],"Creative solutions.")
H("923.d.1.A",4,"Why does separating a problem into elements often lead to better solutions?","Each element can be examined and improved",["It hides the real cause","It makes the problem larger","It removes the need for ideas"],"Analysis.")
H("923.d.1.B",3,"An intern finds five articles on reducing waste and keeps only the two that match her shop's materials and equipment. She is:","critically analyzing information to determine its relevance to the problem-solving process",["keeping every article","choosing at random","ignoring the topic"],"Relevance.")
H("923.d.1.B",4,"Which question best tests whether information is relevant to a problem?","Does this directly help solve what we are facing?",["Is it the longest document?","Is it written in bold?","Is it the first result?"],"Relevance test.")
H("923.d.1.C",3,"An intern lists the cost, speed and risk of buying a new tool versus repairing the old one and uses a decision chart to choose. She is:","comparing and contrasting alternatives using problem-solving and critical-thinking skills",["flipping a coin","ignoring the options","choosing the cheapest without looking"],"Compare options.")
H("923.d.1.C",4,"A decision chart that scores each option on several criteria is useful because it:","makes the trade-offs between choices visible",["picks a winner at random","hides the criteria","removes the need to decide"],"Decision chart.")
H("923.d.1.D",3,"An intern reads the equipment manual, checks a safety data sheet and calls a vendor before choosing a cleaning product. She is:","conducting technical research to gather information necessary for decision making",["guessing which product is best","skipping the manual","choosing by label color"],"Technical research.")
H("923.d.1.D",4,"Which source is best for technical research about a machine's settings?","The manufacturer's official manual",["A rumor from a coworker","An unsigned post online","A hunch"],"Best source.")
H("923.d.2.A",3,"An intern studies how respected team leaders show trust, stay positive during setbacks and give clear direction. She is:","analyzing leadership characteristics related to trusting others and maintaining a positive attitude",["ignoring leaders","copying a bad example","avoiding the team"],"Leadership.")
H("923.d.2.A",4,"A leader who trusts the team usually:","delegates tasks and lets people do them",["checks every small step","takes every job","hides the plan"],"Trust.")
H("923.d.2.B",3,"Three interns assemble a display by splitting the work, passing materials to each other and finishing together. They are:","demonstrating teamwork skills through working cooperatively to achieve goals",["competing for credit","working separately with no plan","arguing about roles"],"Teamwork.")
H("923.d.2.B",4,"Which behavior best supports teamwork?","Sharing information that the whole group needs",["Keeping useful tips private","Doing only your own part and nothing else","Taking credit for group work"],"Support team.")
H("923.d.2.C",3,"After a project, a team holds a quick review where members suggest fixes, agree on two changes and plan to try them next time. They are:","demonstrating teamwork processes that promote team building, consensus and continuous improvement",["ending the discussion early","blaming one member","ignoring the review"],"Team process.")
H("923.d.2.C",4,"Continuous improvement means a team:","keeps looking for ways to do the work better",["never changes its methods","only fixes problems after failure","avoids feedback"],"Improvement.")
H("923.d.2.D",3,"An intern is asked to order supplies for the team and to also finish her own report, and she completes both on schedule. She is:","demonstrating responsibility for group and individual work tasks",["skipping her own report","handing the job off","forgetting the order"],"Responsibility.")
H("923.d.2.D",4,"If a shared task is falling behind, a responsible team member:","speaks up and helps get it back on track",["waits for someone else","hides the problem","blames a teammate"],"Responsible member.")
H("923.d.2.E",3,"An intern thanks a mentor, keeps her commitments and offers to help a busy coworker so the department works well together. She is:","establishing and maintaining effective working relationships in order to accomplish objectives",["avoiding contact","taking help without giving it","breaking promises"],"Working relationships.")
H("923.d.2.E",4,"Good working relationships help a team to:","reach its objectives more smoothly",["lose time","create conflict","avoid goals"],"Objectives.")
H("923.d.2.F",3,"An intern disagrees with a plan, so she asks to talk privately, states her concern calmly and listens to the answer. She is:","demonstrating effective working relationships using interpersonal skills",["complaining to others","shouting in public","saying nothing and resenting it"],"Interpersonal skills.")
H("923.d.2.F",4,"The best time to raise a concern with a coworker is usually:","at a calm moment, in a respectful way",["in front of customers","while angry","never"],"Raise concerns.")
H("923.d.2.G",3,"An intern greets everyone by name, holds a door for a delivery driver and says thanks when a teammate covers for her. She is:","using positive interpersonal skills to work cooperatively with others",["ignoring people","complaining","taking help for granted"],"Positive skills.")
H("923.d.2.G",4,"Which action shows positive interpersonal skills?","Giving sincere appreciation to a coworker",["Rolling your eyes at ideas","Interrupting others","Gossiping about a teammate"],"Appreciation.")
H("923.d.2.H",3,"Two interns both need the only laptop on Friday, so they discuss their deadlines and agree to split the time. They are:","negotiating effectively to arrive at decisions",["arguing until one gives up","taking it without asking","avoiding the issue"],"Negotiation.")
H("923.d.2.H",4,"Effective negotiation begins with:","understanding what each side needs",["demanding your way","staying silent","refusing to talk"],"Negotiation start.")
H("923.d.2.I",3,"An intern learns the customs and holidays of a coworker's culture and makes sure meetings do not fall on an important day. She is:","demonstrating respect for individuals, including those from different cultures, genders and religions",["ignoring differences","making jokes about them","excluding the coworker"],"Respect.")
H("923.d.2.I",4,"Respect for different backgrounds in the workplace helps because it:","lets every person contribute and feel valued",["divides the team","limits who may speak","wastes time"],"Respect value.")
H("923.d.2.J",3,"A manager invites quiet voices to share ideas and treats views from all backgrounds as valuable. She is:","demonstrating sensitivity to and value for diversity",["favoring one group","ignoring some ideas","shutting down discussion"],"Diversity.")
H("923.d.2.J",4,"Valuing diversity on a team helps by:","bringing in a wider range of ideas and experience",["lowering creativity","making people agree on everything","excluding viewpoints"],"Wider ideas.")
H("923.d.3.A",3,"An intern calls a tool a 'micrometer' and not 'the measuring thing' while explaining a measurement to a client. She is:","demonstrating the use of content, technical concepts and vocabulary when analyzing information",["using vague words","avoiding the topic","making up names"],"Vocabulary.")
H("923.d.3.A",4,"Technical vocabulary is most useful when workers:","need to share exact meaning quickly",["want to sound important","avoid being understood","skip details"],"Exact meaning.")
H("923.d.3.B",3,"An intern asks a customer three direct questions about a delivery problem and then summarizes the answer back to her manager. She is:","employing verbal skills when obtaining and conveying information",["guessing the problem","avoiding the customer","mumbling the summary"],"Verbal skills.")
H("923.d.3.B",4,"A strong way to convey information verbally is to:","speak clearly and check that the listener understood",["speak fast and leave","use only slang","avoid eye contact"],"Convey.")
H("923.d.3.C",3,"An intern reads a manufacturer's website and a technical guide to review how a new scheduling tool works before she sets it up. She is:","using informational texts, Internet websites and technical materials to review and implement a procedure",["skipping the guide","guessing the setup","asking no one"],"Reading.")
H("923.d.3.C",4,"After reading a procedure in a technical guide, a worker should:","follow the steps in order and confirm each one",["do the steps from memory","skip the hard ones","change the order"],"Follow steps.")
H("923.d.3.D",3,"An intern notices that a blog post about a repair has no author, no date and no sources, so she checks the manufacturer's page instead. She is:","evaluating the reliability of information from informational texts, Internet websites and technical materials",["trusting the blog","copying it directly","ignoring the issue"],"Reliability.")
H("923.d.3.D",4,"A sign that a source may be unreliable is that it:","gives no author, date or evidence",["cites official standards","lists its sources","is from a recognized organization"],"Unreliable sign.")
H("923.d.3.E",3,"An intern sees a client sigh and check his watch during an explanation, so she shortens her answer and offers a summary. She is:","interpreting verbal and nonverbal cues or behaviors to enhance communication",["talking longer","ignoring the client","getting upset"],"Cues.")
H("923.d.3.E",4,"Which is a nonverbal cue?","A person's posture or facial expression",["The words in an email","A spoken sentence","A printed rule"],"Nonverbal.")
H("923.d.3.F",3,"An intern puts her phone away, makes eye contact and says, 'So the deadline moved to Thursday?' to confirm what her supervisor said. She is:","applying active listening skills to obtain and clarify information",["texting during the meeting","interrupting the supervisor","assuming she knew the answer"],"Active listening.")
H("923.d.3.F",4,"Active listening helps prevent:","mistakes caused by misunderstanding",["clear communication","good teamwork","accurate notes"],"Prevents mistakes.")
H("923.d.3.G",3,"An intern writes a clear email with a short subject line and then explains the same point aloud at the weekly meeting. She is:","using academic skills to facilitate effective written and oral communication",["avoiding both writing and speaking","using only slang","leaving details out"],"Academic skills.")
H("923.d.3.G",4,"Strong grammar and organization in a work email help the reader to:","understand the message quickly",["miss the main point","feel confused","ask for more drafts"],"Writing.")
H("923.d.4.A",3,"An intern in a final-year placement takes on harder tasks in her chosen field, with a mentor reviewing each step. She is:","developing advanced technical knowledge and skills related to her personal career goal",["repeating only beginner tasks","avoiding her field","changing goals daily"],"Advanced.")
H("923.d.4.A",4,"A personal career goal can guide a student's practicum by:","helping her choose tasks that build relevant skills",["limiting all learning","making tasks random","avoiding feedback"],"Goal guide.")
H("923.d.4.B",3,"An intern and her supervisor rate her skills on a form: strong in scheduling, needs work on budgeting. They are:","evaluating technical skill proficiencies",["ignoring the results","praising only","guessing her level"],"Evaluate skills.")
H("923.d.4.B",4,"The main purpose of evaluating technical skill proficiency is to:","find out what to practice or improve next",["assign blame","avoid training","hide weak areas"],"Purpose.")
H("923.d.4.C",3,"An intern's supervisor says her reports are too long, and she asks for an example and rewrites the next one. She is:","accepting critical feedback provided by the supervisor",["defending the old reports","ignoring the note","complaining about the supervisor"],"Take feedback.")
H("923.d.4.C",4,"Which response to critical feedback is most productive?","Ask clarifying questions and apply the suggestions",["Argue every point","Stay silent and change nothing","Blame another coworker"],"Productive response.")
H("923.d.5.B",3,"At a school expo, an intern walks local employers through her portfolio and answers their questions. She is:","presenting the portfolio to interested stakeholders",["leaving the portfolio at home","avoiding the employers","refusing questions"],"Present.")
H("923.d.5.B",4,"A student who prepares to present her portfolio should:","practice explaining each item and its purpose",["read it word for word","skip the practice","hide weak samples"],"Prepare.")
H("923.d.5.A.i",3,"An intern adds the certifications and competency checklists she earned this term to her portfolio. She is:","updating a professional portfolio to include attainment of technical skill competencies",["leaving the portfolio blank","removing her records","copying someone else's"],"Skill attainment.")
H("923.d.5.A.i",4,"Which item shows attainment of a technical skill competency?","A signed competency checklist",["A lunch menu","A class schedule only","A blank form"],"Competency evidence.")
H("923.d.5.A.ii",3,"An intern adds notes about a job shadow and a summer workshop to her portfolio. She is:","updating a professional portfolio to include extended learning experiences",["leaving out her experiences","deleting the notes","guessing the dates"],"Extended learning.")
H("923.d.5.A.ii",4,"A workshop outside of class could be listed in a portfolio as:","an extended learning experience",["a grade report","a disciplinary note","a lunch order"],"Extended.")
H("923.d.5.A.iii",3,"An intern writes a one-paragraph abstract of the technical writing she completed and puts it in her portfolio. She is:","updating a professional portfolio to include an abstract of technical writing",["skipping technical writing","leaving out her work","copying a textbook"],"Abstract.")
H("923.d.5.A.iii",4,"An abstract of technical writing is best described as:","a short summary of the main points of the work",["the full document","a table of prices","a list of names"],"Abstract def.")
H("923.d.5.A.iv",3,"An intern revises her resume to list her new skills and attaches it to her portfolio. She is:","updating a professional portfolio to include a resume",["leaving the old one","deleting it","using a template without changes"],"Resume.")
H("923.d.5.A.iv",4,"A hiring manager flips to the resume page of a student portfolio. Which version makes the best impression?","One that is current, accurate and easy to scan",["One that is three years old","One packed with unrelated details","One with several typos"],"A strong resume is current and clear.")
H("923.d.5.A.v",3,"An intern includes a flyer she designed, a photo of a display she built and a short report as examples of her work. She is:","updating a professional portfolio to include samples of work",["throwing away her projects","using strangers' work","leaving it empty"],"Samples.")
H("923.d.5.A.v",4,"Samples of work show employers:","what the student can actually produce",["her schedule","her lunch choices","her favorite colors"],"Show ability.")
H("923.d.5.A.vi",3,"An intern places her supervisor's signed evaluation of her performance in her portfolio. She is:","updating a professional portfolio to include an evaluation from a supervisor",["removing feedback","hiding results","leaving it out"],"Evaluation.")
H("923.d.5.A.vi",4,"Why would an employer value a supervisor's evaluation in a portfolio?","It gives an outside view of the student's performance",["It replaces an interview","It lists the pay rate","It shows the student's schedule"],"Outside view.")
B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "batches", "cte_152.jsonl"))
